import os
import requests

def fetch_recent_logs(payload, config=None):
    config = config or {}
    url = "https://api.logz.io/v1/logs"
    headers = {
        "Content-Type": "application/json",
        "X-Token": config.get("logzio_token", os.getenv("LOGZIO_TOKEN"))
    }
    query = {
        "query": f"{payload['field']}:\"{payload['value']}\"",
        "from": payload['from'],
        "to": payload['to'],
        "size": 100
    }
    response = requests.get(url, headers=headers, params=query)
    result = response.json()
    return result
